<script setup lang="ts">
  import User from '@/@core/components/icons/user.vue'
  import { locationsApi } from '@/api'

  const props = defineProps<{
    siteId: number | string
  }>()

  const emit = defineEmits<{ close: [] }>()
  const dialog = defineModel<boolean>({ required: true })

  const tab = ref('site-details')
  const selectedsite = ref<Record<string, any> | null>(null)
  const isSiteDetailsLoading = ref(false)

  const fetchSelectedSiteData = async () => {
    isSiteDetailsLoading.value = true
    try {
      const response = await locationsApi.getById(props.siteId)
      if (response.data?.data) {
        selectedsite.value = response.data.data
      }
    } catch (err: any) {
      // error handled by fetching component
    } finally {
      isSiteDetailsLoading.value = false
    }
  }

  onMounted(() => { fetchSelectedSiteData() })
</script>

