                      <div class="text-secondary mb-2">العنوان التفصيلي</div>
                      <div v-if="isSiteDetailsLoading"><v-skeleton-loader style="width: 100%; max-width: 200px" type="subtitle" /></div>
                      <div v-else class="text-dark">{{ selectedsite?.address }}</div>
                    </div>
                  </v-col>
                  <v-col class="d-flex gap-2" cols="12">
                    <span>
                      <svg
                        fill="none"
                        height="26"
                        viewBox="0 0 24 26"
                        width="24"
                        xmlns="http://www.w3.org/2000/svg"
