                    <div xlass="w-100">
                      <div class="text-secondary mb-2">إجمالي الساعات هذا الأسبوع</div>
                      <div v-if="isSiteDetailsLoading"><v-skeleton-loader style="width: 100%; max-width: 200px" type="subtitle" /></div>
                      <div v-else class="text-dark">{{ selectedsite?.workHours }}</div>
                    </div>
                  </v-col>
                </v-row>
              </VCardText>
            </VCard>
          </v-window-item>

          <v-window-item class="px-2 py-3" value="observers">
            <v-card class="px-4 border">
              <v-card-title class="px-0"><h5>المشرف</h5></v-card-title>
              <v-divider />
              <VCardText class="px-0">
                <v-skeleton-loader v-if="isSiteDetailsLoading" type="article" />
                <div v-else-if="selectedsite?.supervisor">
                  <v-card class="border border-light mb-2" rounded="lg">
                    <VCardTitle class="d-flex ga-2">
                      <span><User :size="45" /></span>
                      <div class="d-flex flex-column">
                        <h5 class="mb-0">{{ selectedsite.supervisor.fullName }}</h5>
                        <span class="text-xs text-secondary" size="small">{{ selectedsite.supervisor.userType?.name?.ar }}</span>
                      </div>
                    </VCardTitle>
                    <v-divider />
                    <VCardText class="px-2 py-4">
                      <v-row class="mx-0">
                        <v-col class="d-flex gap-2" cols="12" sm="6">
                          <div class="text-xs font-bold">
                            <div class="text-secondary mb-2">ساعات العمل</div>
                            <div class="text-dark">{{ selectedsite.supervisor.monthlyWorkingHours }} ساعة هذا الشهر</div>
                          </div>
                        </v-col>
                        <v-col class="d-flex gap-2" cols="12" sm="6">
                          <div class="text-xs font-bold">
                            <div class="text-secondary mb-2">آخر تسجيل حضور</div>
                            <div class="text-dark">{{ selectedsite.supervisor.todayCheckIn || 'لم يسجل' }}</div>
                          </div>
                        </v-col>
                      </v-row>
                    </VCardText>
                  </v-card>
                </div>
                <div v-else class="py-5 text-center text-grey"><p>لا يوجد مشرف لهذا الموقع</p></div>
              </VCardText>
            </v-card>
          </v-window-item>

          <v-window-item class="px-2 py-3" value="employees">
            <v-card class="px-4 border">
              <v-card-title class="px-0"><h5>الموظفون</h5></v-card-title>
              <v-divider />
              <VCardText class="px-0">
                <v-skeleton-loader v-if="isSiteDetailsLoading" type="article" />
                <v-card
                  v-for="(emp, idx) in selectedsite?.inspectors"
                  v-else
                  :key="idx"
                  class="border border-light mb-2"
                  rounded="lg"
                >
                  <VCardTitle class="d-flex ga-2">
                    <span><User :size="45" /></span>
                    <div class="d-flex flex-column">
                      <h5 class="mb-0">{{ emp.fullName }}</h5>
                      <span class="text-xs text-secondary" size="small">{{ emp.userType?.name?.ar }}</span>
                    </div>
                  </VCardTitle>
                  <v-divider />
                  <VCardText class="px-2 py-4">
                    <v-row class="mx-0">
                      <v-col class="d-flex gap-2" cols="12" sm="6">
                        <div class="text-xs font-bold">
                          <div class="text-secondary mb-2">ساعات العمل</div>
                          <div class="text-dark">{{ emp.monthlyWorkingHours }} ساعة هذا الشهر</div>
                        </div>
                      </v-col>
                      <v-col class="d-flex gap-2" cols="12" sm="6">
                        <div class="text-xs font-bold">
                          <div class="text-secondary mb-2">آخر تسجيل حضور</div>
                          <div class="text-dark">{{ emp.todayCheckIn || 'لم يسجل' }}</div>
                        </div>
                      </v-col>
                    </v-row>
                  </VCardText>
                </v-card>
                <div v-if="!selectedsite?.inspectors?.length && !isSiteDetailsLoading" class="py-5 text-center text-grey"><p>لا يوجد موظفون لهذا الموقع</p></div>
              </VCardText>
            </v-card>
          </v-window-item>
        </v-window>
      </v-card-text>
    </v-card>
  </v-dialog>
</template>
